package com.example.kmp.feature.${feature}.component

import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier

/** Part of the ${feature} screen that no other screen uses. */
@Composable
internal fun ${name}(
    name: String,
    modifier: Modifier = Modifier,
) {
    Text(text = name, modifier = modifier)
}

package com.example.kmp.data.user

/** Reads ${name} data. */
interface ${name}Repository {
    fun items(): List<${item}>
}

package com.example.kmp.data.user

/** The real implementation. A stub, like [UserRepositoryImpl]. */
class ${name}RepositoryImpl : ${name}Repository {
    override fun items(): List<${item}> = emptyList()
}
